DF1_S03P04"},{"ref":"SA-SC-089","nom":"Tray 1 cassette C — tête 1 tray 3 · fibre 5","src":"SA-S1-R1-ODF1_S03P05","dst":"SC-S1-R1-ODF1_S03P05"},{"ref":"SA-SC-090","nom":"Tray 1 cassette C — tête 1 tray 3 · fibre 6","src":"SA-S1-R1-ODF1_S03P06","dst":"SC-S1-R1-ODF1_S03P06"},{"ref":"SA-SC-091","nom":"Tray 1 cassette C — tête 1 tray 3 · fibre 7","src":"SA-S1-R1-ODF1_S03P07","dst":"SC-S1-R1-ODF1_S03P07"},{"ref":"SA-SC-092","nom":"Tray 1 cassette C — tête 1 tray 3 · fibre 8","src":"SA-S1-R1-ODF1_S03P08","dst":"SC-S1-R1-ODF1_S03P08"},{"ref":"SA-SC-093","nom":"Tray 1 cassette C — tête 1 tray 3 · fibre 9","src":"SA-S1-R1-ODF1_S03P09","dst":"SC-S1-R1-ODF1_S03P09"},{"ref":"SA-SC-094","nom":"Tray 1 cassette C — tête 1 tray 3 · fibre 10","src":"SA-S1-R1-ODF1_S03P10","dst":"SC-S1-R1-ODF1_S03P10"},{"ref":"SA-SC-095","nom":"Tray 1 cassette C — tête 1 tray 3 · fibre 11","src":"SA-S1-R1-ODF1_S03P11","dst":"SC-S1-R1-ODF1_S03P11"},{"ref":"SA-SC-096","nom":"Tray 1 cassette C — tête 1 tray 3 · fibre 12","src":"SA-S1-R1-ODF1_S03P12","dst":"SC-S1-R1-ODF1_S03P12"},{"ref":"SA-SC-097","nom":"Tray 1 cassette D — tête 1 tray 4 · fibre 1","src":"SA-S1-R1-ODF1_S04P01","dst":"SC-S1-R1-ODF1_S04P01"},{"ref":"SA-SC-098","nom":"Tray 1 cassette D — tête 1 tray 4 · fibre 2","src":"SA-S1-R1-ODF1_S04P02","dst":"SC-S1-R1-ODF1_S04P02"},{"ref":"SA-SC-099","nom":"Tray 1 cassette D — tête 1 tray 4 · fibre 3","src":"SA-S1-R1-ODF1_S04P03","dst":"SC-S1-R1-ODF1_S04P03"},{"ref":"SA-SC-100","nom":"Tray 1 cassette D — tête 1 tray 4 · fibre 4","src":"SA-S1-R1-ODF1_S04P04","dst":"SC-S1-R1-ODF1_S04P04"},{"ref":"SA-SC-101","nom":"Tray 1 cassette D — tête 1 tray 4 · fibre 5","src":"SA-S1-R1-ODF1_S04P05","dst":"SC-S1-R1-ODF1_S04P05"},{"ref":"SA-SC-102","nom":"Tray 1 cassette D — tête 1 tray 4 · fibre 6","src":"SA-S1-R1-ODF1_S04P06","dst":"SC-S1-R1-ODF1_S04P06"},{"ref":"SA-SC-103","nom":"Tray 1 cassette D — tête 1 tray 4 · fibre 7","src":"SA-S1-R1-ODF1_S04P07","dst":"SC-S1-R1-ODF1_S04P07"},{"ref":"SA-SC-104","nom":"Tray 1 cassette D — tête 1 tray 4 · fibre 8","src":"SA-S1-R1-ODF1_S04P08","dst":"SC-S1-R1-ODF1_S04P08"},{"ref":"SA-SC-105","nom":"Tray 1 cassette D — tête 1 tray 4 · fibre 9","src":"SA-S1-R1-ODF1_S04P09","dst":"SC-S1-R1-ODF1_S04P09"},{"ref":"SA-SC-106","nom":"Tray 1 cassette D — tête 1 tray 4 · fibre 10","src":"SA-S1-R1-ODF1_S04P10","dst":"SC-S1-R1-ODF1_S04P10"},{"ref":"SA-SC-107","nom":"Tray 1 cassette D — tête 1 tray 4 · fibre 11","src":"SA-S1-R1-ODF1_S04P11","dst":"SC-S1-R1-ODF1_S04P11"},{"ref":"SA-SC-108","nom":"Tray 1 cassette D — tête 1 tray 4 · fibre 12","src":"SA-S1-R1-ODF1_S04P12","dst":"SC-S1-R1-ODF1_S04P12"},{"ref":"SA-SC-109","nom":"Tray 1 cassette E — tête 1 tray 5 · fibre 1","src":"SA-S1-R1-ODF1_S05P01","dst":"SC-S1-R1-ODF1_S05P01"},{"ref":"SA-SC-110","nom":"Tray 1 cassette E — tête 1 tray 5 · fibre 2","src":"SA-S1-R1-ODF1_S05P02","dst":"SC-S1-R1-ODF1_S05P02"},{"ref":"SA-SC-111","nom":"Tray 1 cassette E — tête 1 tray 5 · fibre 3","src":"SA-S1-R1-ODF1_S05P03","dst":"SC-S1-R1-ODF1_S05P03"},{"ref":"SA-SC-112","nom":"Tray 1 cassette E — tête 1 tray 5 · fibre 4","src":"SA-S1-R1-ODF1_S05P04","dst":"SC-S1-R1-ODF1_S05P04"},{"ref":"SA-SC-113","nom":"Tray 1 cassette E — tête 1 tray 5 · fibre 5","src":"SA-S1-R1-ODF1_S05P05","dst":"SC-S1-R1-ODF1_S05P05"},{"ref":"SA-SC-114","nom":"Tray 1 cassette E — tête 1 tray 5 · fibre 6","src":"SA-S1-R1-ODF1_S05P06","dst":"SC-S1-R1-ODF1_S05P06"},{"ref":"SA-SC-115","nom":"Tray 1 cassette E — tête 1 tray 5 · fibre 7","src":"SA-S1-R1-ODF1_S05P07","dst":"SC-S1-R1-ODF1_S05P07"},{"ref":"SA-SC-116","nom":"Tray 1 cassette E — tête 1 tray 5 · fibre 8","src":"SA-S1-R1-ODF1_S05P08","dst":"SC-S1-R1-ODF1_S05P08"},{"ref":"SA-SC-117","nom":"Tray 1 cassette E — tête 1 tray 5 · fibre 9","src":"SA-S1-R1-ODF1_S05P09","dst":"SC-S1-R1-ODF1_S05P09"},{"ref":"SA-SC-118","nom":"Tray 1 cassette E — tête 1 tray 5 · fibre 10","src":"SA-S1-R1-ODF1_S05P10","dst":"SC-S1-R1-ODF1_S05P10"},{"ref":"SA-SC-119","nom":"Tray 1 cassette E — tête 1 tray 5 · fibre 11","src":"SA-S1-R1-ODF1_S05P11","dst":"SC-S1-R1-ODF1_S05P11"},{"ref":"SA-SC-120","nom":"Tray 1 cassette E — tête 1 tray 5 · fibre 12","src":"SA-S1-R1-ODF1_S05P12","dst":"SC-S1-R1-ODF1_S05P12"}]}$json$::jsonb;
  r     record;
  n     int;
  v_cab int;
  v_trg text[] := '{}';
  v_t   text;
BEGIN
  INSERT INTO public.tenants (name, slug) VALUES ('Omega Tech', 'omega-tech')
  ON CONFLICT (slug) DO NOTHING;
  SELECT id INTO v_tid FROM public.tenants WHERE slug = 'omega-tech';
  -- Les triggers de cascade (site → salle → rack → ODF → slot → ports) et les valeurs
  -- par défaut lisent le tenant dans ce paramètre quand on n'est pas connecté via l'API.
  PERFORM set_config('app.tenant_id', v_tid::text, true);

  IF EXISTS (SELECT 1 FROM public.sites WHERE tenant_id = v_tid AND id IN ('SA', 'SB', 'SC')) THEN
    RAISE NOTICE 'Import déjà présent pour Omega Tech : rien à faire';
    RETURN;
  END IF;

  -- Le statut OCCUPE est importé tel quel depuis les classeurs, sans service/CID associé :
  -- on suspend uniquement pendant l'import le trigger (s'il existe, quel que soit son nom)
  -- qui remettrait le statut à LIBRE faute de CID.
  FOR r IN
    SELECT t.tgname FROM pg_trigger t JOIN pg_proc p ON p.oid = t.tgfoid
    WHERE t.tgrelid = 'public.ports'::regclass AND NOT t.tgisinternal
      AND p.proname = 'fn_ports_sync_statut_from_cid' AND t.tgenabled <> 'D'
  LOOP
    EXECUTE format('ALTER TABLE public.ports DISABLE TRIGGER %I', r.tgname);
    v_trg := array_append(v_trg, r.tgname);
  END LOOP;

  -- 1. Sites (le trigger crée salle S1, rack R1, ODF1, slot S01 et ses 12 ports)
  INSERT INTO public.sites (tenant_id, id, name, description)
  SELECT v_tid, x.id, x.name, x.description
  FROM jsonb_to_recordset(d->'sites') AS x(id text, name text, description text);

  -- 2. Racks
  INSERT INTO public.racks (tenant_id, id, site_id, salle_id, name, description)
  SELECT v_tid, x.id, x.site, x.site || '-S1', x.name, x.description
  FROM jsonb_to_recordset(d->'racks') AS x(id text, site text, name text, description text)
  ON CONFLICT (tenant_id, id) DO UPDATE SET description = EXCLUDED.description;

  -- 3. ODF
  INSERT INTO public.odfs (tenant_id, id, rack_id, name, route, slots)
  SELECT v_tid, x.id, x.rack, x.name, x.route, x.slots
  FROM jsonb_to_recordset(d->'odfs') AS x(id text, rack text, name text, route text, slots int)
  ON CONFLICT (tenant_id, id) DO UPDATE SET route = EXCLUDED.route, slots = EXCLUDED.slots;

  -- 4. Slots (le trigger crée les 12 ports de chacun)
  FOR r IN SELECT x.id, x.slots FROM jsonb_to_recordset(d->'odfs') AS x(id text, slots int) LOOP
    FOR i IN 1 .. r.slots LOOP
      INSERT INTO public.slots (tenant_id, id, odf_id, slot_num, name)
      VALUES (v_tid, r.id || '_S' || LPAD(i::text, 2, '0'), r.id, i, 'S' || LPAD(i::text, 2, '0'))
      ON CONFLICT (tenant_id, id) DO NOTHING;
    END LOOP;
  END LOOP;

  -- 5. Détail des ports
  UPDATE public.ports p
  SET statut      = x.statut,
      ot_num      = nullif(x.ot, ''),
      capacite    = nullif(x.cap, ''),
      owner       = nullif(x.owner, ''),
      destination = nullif(x.dest, ''),
      remarques   = nullif(x.rem, '')
  FROM jsonb_to_recordset(d->'ports')
       AS x(id text, statut text, ot text, cap text, owner text, dest text, rem text)
  WHERE p.tenant_id = v_tid AND p.id = x.id;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> jsonb_array_length(d->'ports') THEN
    RAISE EXCEPTION 'Ports mis à jour : % sur % attendus', n, jsonb_array_length(d->'ports');
  END IF;

  -- 6. Câbles inter-sites (site A ↔ site C) ; les triggers occupent les ports
  INSERT INTO public.cables_fibre
    (tenant_id, id, cable_reference, nom, type_lien, nombre_fibres, port_source_id, port_dest_id)
  SELECT v_tid, x.ref, x.ref, x.nom, 'EXTERNE', 2, x.src, x.dst
  FROM jsonb_to_recordset(d->'cables') AS x(ref text, nom text, src text, dst text);
  GET DIAGNOSTICS v_cab = ROW_COUNT;

  FOREACH v_t IN ARRAY v_trg LOOP
    EXECUTE format('ALTER TABLE public.ports ENABLE TRIGGER %I', v_t);
  END LOOP;

  RAISE NOTICE 'Import Omega Tech terminé : % sites, % racks, % ODF, % ports renseignés, % câbles',
    jsonb_array_length(d->'sites'), jsonb_array_length(d->'racks'), jsonb_array_length(d->'odfs'), n, v_cab;
END
$import$;
